<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Payment receipt</title><link rel="stylesheet" href="<?= base_url('css/checkout.css?v=20261126-1') ?>"></head><body><main class="checkout-shell"><header class="checkout-header"><span class="gateway-brand"><span class="material-symbols-outlined" aria-hidden="true">receipt_long</span>Payment Gateway</span></header><p class="demo-disclosure"><span class="material-symbols-outlined" aria-hidden="true">info</span>Academic payment simulation: no real funds were transferred.</p><section class="checkout-card"><p class="eyebrow">TechReserve</p><h1>Payment receipt</h1><dl class="receipt-details"><div><dt>Transaction reference</dt><dd><?= esc($payment['transaction_reference']) ?></dd></div><div><dt>Gateway transaction</dt><dd><?= esc($payment['gateway_transaction_id']) ?></dd></div><div><dt>Reservation reference</dt><dd><?= esc($payment['reservation_reference']) ?></dd></div><div><dt>Student</dt><dd><?= esc($payment['student_name']) ?> (<?= esc($payment['student_id']) ?>)</dd></div><div><dt>Method</dt><dd><?= esc(['gcash'=>'GCash','card'=>'Credit / Debit Card','bank_transfer'=>'Bank Transfer'][$payment['payment_method']] ?? $payment['payment_method']) ?></dd></div><div><dt>Amount</dt><dd><?= esc($payment['currency']) ?> <?= esc($payment['amount']) ?></dd></div><div><dt>Status</dt><dd><?= esc(ucfirst($payment['payment_status'])) ?></dd></div><div><dt>Paid</dt><dd><?= esc($payment['paid_at'] ?? 'Not paid') ?></dd></div></dl><h2>Resources</h2><ul><?php foreach ($payment['rented_items_list'] as $item): ?><li><?= esc($item['name']) ?> — <?= (int) $item['quantity'] ?> <?= esc($item['type']) ?></li><?php endforeach ?></ul><p><button type="button" onclick="window.print()">Print receipt</button></p></section></main></body></html>
